import sys
from collections import defaultdict


def gene_symbol(target):
    fields = target.split("|")
    return fields[5].upper() if len(fields) > 5 and fields[5] else fields[0].upper()


def better(a, b):
    """Return True when alignment a is preferable to alignment b."""
    return (a[4], a[2] - a[1], a[5]) > (b[4], b[2] - b[1], b[5])


def best_chain(intervals, overlap_tolerance=12):
    intervals = sorted(intervals, key=lambda x: (x[2], x[1]))
    if not intervals:
        return [], 0.0
    scores = []
    chains = []
    for i, item in enumerate(intervals):
        length = item[2] - item[1]
        weight = length * item[5]
        best_score = weight
        best_items = [item]
        for j in range(i):
            prev = intervals[j]
            if prev[2] <= item[1] + overlap_tolerance:
                candidate_score = scores[j] + weight
                if candidate_score > best_score:
                    best_score = candidate_score
                    best_items = chains[j] + [item]
        scores.append(best_score)
        chains.append(best_items)
    k = max(range(len(scores)), key=lambda i: scores[i])
    return chains[k], scores[k]


def union_length(intervals):
    merged = []
    for start, end in sorted(intervals):
        if not merged or start > merged[-1][1]:
            merged.append([start, end])
        elif end > merged[-1][1]:
            merged[-1][1] = end
    return sum(end - start for start, end in merged)


